class Solution:
    def grayCode(self, n: int) -> List[int]:
        return [i ^ (i >> 1) for i in range(1 << n)]

class Solution {
public:
    vector<int> grayCode(int n) {
        vector<int> res;
        res.reserve(1 << n);
        for (int i = 0; i < (1 << n); i++) {
            res.push_back(i ^ (i >> 1));
        }
        return res;
    }
};

class Solution {
    public List<Integer> grayCode(int n) {
        List<Integer> res = new ArrayList<>(1 << n);
        for (int i = 0; i < (1 << n); i++) {
            res.add(i ^ (i >> 1));
        }
        return res;
    }
}

var grayCode = function(n) {
    const res = [];
    const total = 1 << n;
    for (let i = 0; i < total; i++) {
        res.push(i ^ (i >> 1));
    }
    return res;
};
